Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include<cstdio>
#include<iostream>
#include<cmath>
#include<cfloat>
#define INF 1000000000
using namespace std;

float Tabs(double n){
    if(n>=0) return n;
    return -n;
}

int solve_it(int x,int y,int b){
    double target = (double)x/y;
    int lb=0,ub=1000000;
    for(int i=0; i<25; i++){
        int a = (lb+ub)/2;
        if((double)a/b < target) lb = a;
        else ub = a;
    }
    int res;
    double diff=DBL_MAX;
    for(int a=lb-10; a<=ub+10; a++){
        double d = Tabs((double)a/b - target);
        if(d < diff){
            diff = d;
            res = a;
        }
    }
    return res;
}

int main(){
    int x,y,n;
    scanf("%d %d %d",&x,&y,&n);
    int ans1,ans2;
    double best_diff=DBL_MAX;
    for(int b=1; b<=n; b++){
        int a = solve_it(x,y,b);
        double d = Tabs((double)a/b - (double)x/y);
        if(d < best_diff) {
            best_diff = d;
            ans1 = a; ans2 = b;
        }
    }
    printf("%d/%d\n",ans1,ans2);
    return 0;
}

